mapper.select:
SELECT

FROM drug_expiry_alert a
LEFT JOIN drug_info d ON a.drug_id = d.id
LEFT JOIN hospital h ON a.hospital_id = h.id

    AND a.drug_id = #{drugId}
    AND a.hospital_id = #{hospitalId}
    AND a.alert_level = #{alertLevel}
    AND a.status = #{status}

ORDER BY a.days_to_expire ASC, a.created_at DESC
